node --input-type=module -e 'import fs from "node:fs";import cp from "node:child_process";import path from "node:path";import crypto from "node:crypto";import assert from "node:assert/strict";
const agp="/home/apnex/taceng/agp";
const recordPath="docs/reviews/browser-peer-scale-assurance/browser-scale-execution-readiness-checks.json";
const record=JSON.parse(fs.readFileSync(recordPath,"utf8"));
const sha=b=>crypto.createHash("sha256").update(b).digest("hex");
const git=(cwd,...args)=>cp.execFileSync("git",args,{cwd,encoding:"utf8"});
const tracking=new Set(record.trackingChanges.map(e=>e[0]));
const results=[];
for(const [cwd,before] of Object.entries(record.baseline).filter(([k])=>k.startsWith("/"))) {
 assert.equal(git(cwd,"rev-parse","HEAD").trim(),before.head);
 assert.equal(git(cwd,"rev-parse","refs/remotes/origin/main").trim(),before.origin);
 assert.equal(git(cwd,"diff","--cached","--binary"),before.index);
 const dirty=git(cwd,"ls-files","--modified","--others","--exclude-standard","-z").split("\0").filter(Boolean);
 const expected=cwd===agp?[...before.dirty,...record.allowedNewFiles]:before.dirty;
 assert.deepEqual([...dirty].sort(),[...expected].sort());
 if(cwd!==agp)assert.equal(git(cwd,"status","--porcelain=v1","--untracked-files=all"),before.status);
 let unchanged=0;
 for(const [p,h] of Object.entries(before.files)){
  if(cwd===agp&&tracking.has(p))continue;
  assert.equal(sha(fs.readFileSync(path.join(cwd,p))),h,p+" changed");unchanged++;
 }
 results.push({repository:cwd,head:before.head,localOrigin:before.origin,indexUnchanged:true,indexEmpty:before.index==="",dirtyPaths:dirty.length,unchangedComparedFiles:unchanged,newFiles:cwd===agp?record.allowedNewFiles:[]});
}
for(const file of tracking){
 let text=fs.readFileSync(file,"utf8");
 for(const [p,oldText,newText] of record.trackingChanges.filter(e=>e[0]===file)) {
  assert.equal(text.split(newText).length-1,1,p+" replacement not unique");
  text=text.replace(newText,oldText);
 }
 if(file==="docs/VERIFICATION.md"){
  assert.equal(text.split(record.addedVerificationSection).length-1,1,"new checkpoint not unique");
  text=text.replace(record.addedVerificationSection,"");
 }
 assert.equal(sha(Buffer.from(text)),record.baseline[agp].files[file],file+" inverse-content mismatch");
}
for(const source of record.sourceIdentity.files)assert.equal(sha(fs.readFileSync(source.path)),source.sha256,source.path+" changed");
const packet=git(agp,"ls-files","docs/reviews/browser-peer-scale-assurance","-z").split("\0").filter(Boolean);
assert.equal(packet.length,20);
for(const p of [...packet,"VISION.md","docs/DECISIONS.md"])assert.equal(sha(fs.readFileSync(p)),sha(cp.execFileSync("git",["show",record.baseline[agp].head+":"+p],{cwd:agp})),p+" differs from reviewed commit");
const review=JSON.parse(fs.readFileSync("docs/reviews/browser-peer-scale-assurance/browser-scale-key-recheck-checks-02.json","utf8"));
assert.equal(sha(fs.readFileSync(review.independentReview.report.path)),review.independentReview.report.sha256);
const artifacts=[...record.allowedNewFiles.filter(p=>p!==recordPath),"docs/BOARD.md","docs/VERIFICATION.md"].map(p=>{const b=fs.readFileSync(p);return{path:p,bytes:b.length,sha256:sha(b)}});
console.log(JSON.stringify({result:"PASS",repositories:results,committedPacketFilesUnchanged:packet.length,normativeFilesMatchReviewedCommit:["VISION.md","docs/DECISIONS.md"],otherDirtyFilesUnchanged:record.baseline[agp].dirty.length-tracking.size,exactTrackingEdits:record.trackingChanges.map(([file,oldText,newText])=>({file,oldText,newText})),verificationHistoryPreserved:true,sourceIdentityFilesPreserved:record.sourceIdentity.files.length,rawReportMatchesCapturedDigest:true,artifacts,scope:"File bytes, Git state, allowed path set and inverse-content preservation only; not independent semantic or execution assurance"},null,2));'

